/*
 * Focused model of the bit_putcs glyph-index arithmetic, used only to
 * demonstrate the security invariant dynamically:
 *   - "baseline" reproduces the pre-fix expression and reads out of bounds
 *   - "patched"  applies the reference clamp and stays in bounds
 * This models the arithmetic; the actual kernel function is validated by
 * compiling drivers/video/fbdev/core/bitblit.o.
 */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define CELLSIZE 16u
#define CHARCOUNT 256u
#define HI_FONT_MASK 0x100u

int main(int argc, char **argv)
{
    int patched = (argc > 1 && strcmp(argv[1], "patched") == 0);
    unsigned char *data = malloc(CHARCOUNT * CELLSIZE);
    unsigned int charcnt = CHARCOUNT;
    unsigned int cellsize = CELLSIZE;
    uint16_t charmask = HI_FONT_MASK ? 0x1ff : 0xff; /* vc_hi_font_mask set */
    uint16_t cell = 0x100;                            /* screen cell value */
    uint16_t ch = cell & charmask;                    /* == 256, >= charcnt */
    unsigned int idx;
    volatile unsigned char v;

    if (!data)
        return 2;

    if (patched) {
        unsigned int charcnt_local = charcnt; /* charcnt = vc->vc_font.charcount */
        if (ch >= charcnt_local)
            ch = 0;
    }
    idx = (unsigned int)ch;

    v = data[idx * cellsize]; /* baseline: OOB read at end of font array */
    printf("%s: masked=%u index=%u read=%u (font bytes=%u, max valid offset=%u)\n",
           patched ? "patched" : "baseline", cell & charmask, idx, v,
           CHARCOUNT * CELLSIZE, CHARCOUNT * CELLSIZE - 1);
    free(data);
    return 0;
}

